runs.stdout:
{"cents": 999, "coupon": true, "result": 999}
{"cents": 1000, "coupon": true, "result": 1000}
{"cents": 1001, "coupon": true, "result": 901}
{"cents": 1000, "coupon": false, "result": 1000}
{"cents": 0, "coupon": true, "result": 0}
{"cents": -1, "coupon": true, "error": "nonnegative integer cents required"}
{"cents": 1.5, "coupon": true, "error": "nonnegative integer cents required"}

argv:
import json
from api import quote
checks=[]
for cents,coupon,expected in [(999,True,999),(1000,True,900),(1001,True,901),(1000,False,1000),(0,True,0),(1001,False,1001),(10**100,True,10**100-100)]:
    actual=quote(cents,coupon)
    checks.append({"cents":cents,"coupon":coupon,"actual":actual,"expected":expected,"pass":actual==expected})
for cents in [-1,1.5,True,"1000",None]:
    try: actual=quote(cents,True)
    except ValueError as e: actual=str(e)
    checks.append({"cents":cents,"actual":actual,"expected":"nonnegative integer cents required","pass":actual=="nonnegative integer cents required"})
print(json.dumps(checks))
assert all(c["pass"] for c in checks), "approved quote contract violated"

